Given the root of a binary tree, find the maximum depth of the tree. The maximum depth or height of the tree is the number of edges in the tree from the root to the deepest node.Examples:Input: Output: 2Explanation: The longest path from the root node to deepest node has 2 edges.Input:  Output: 3Explanation: The longest path from the root (node 1) to deepest leaf (node 6) has 3 edges.Try It YourselfTable of ContentUsing RecursionLevel Order Traversal Using RecursionThe idea is to recursively compute the height of the left and right subtrees for each node. The height of the current node is then calculated by 1 + max(leftHeight, rightHeight). The recursion bottoms out when we reach to a null node, which contributes a height of 0.Consider the following tree for example to understand the flow.maxDepth('12') = max(maxDepth('8'), maxDepth('18')) + 1 = 1 + 1 = 2because recursively maxDepth('8') =  max (maxDepth('5'), maxDepth('11')) + 1 = 0 + 1 maxDepth('18') = max (maxDepth(NULL), maxDepth('NULL)) + 1 = -1 + 1 = 0maxDepth("5") = max (maxDepth(NULL), maxDepth('NULL)) + 1 = -1 + 1 = 0maxDepth("11") = max (maxDepth(NULL), maxDepth('NULL)) + 1 = -1 + 1 = 0
            C++

    #include <iostream>
using namespace std;

// Node structure
class Node {
public:
    int data;
    Node *left;
    Node *right;

    Node(int val) {
        data = val;
        left = nullptr;
        right = nullptr;
    }
};

int height(Node *root) {
    if (root == nullptr)
        return -1;

    // compute the height of left and right subtrees
    int lHeight = height(root->left);
    int rHeight = height(root->right);

    return max(lHeight, rHeight) + 1;
}

int main() {

    // Representation of the input tree:
    //     12
    //    /  \
    //   8   18
    //  / \
    // 5   11
    Node *root = new Node(12);
    root->left = new Node(8);
    root->right = new Node(18);
    root->left->left = new Node(5);
    root->left->right = new Node(11);

    cout << height(root);

    return 0;
}


